const ctx = $('Process input').first().json;
const state = ctx.state;
const now = new Date().toISOString();
const newMessages = [];
let analysis = { user: null, reply: null };
let goalUpdate = null;
let followUp = false;
if (ctx.hasUserMessage) {
  const userA = $('Analyze user sentiment and emotion').first().json.output || {};
  const reply = String($('Generate persona reply').first().json.text || '').trim();
  const replyA = $('Analyze reply sentiment and emotion').first().json.output || {};
  const ev = $('Evaluate current goal').first().json.output || {};
  const lastUser = state.messages[state.messages.length - 1];
  if (lastUser && lastUser.role === 'user') lastUser.analysis = userA;
  let parts = reply.split(/\n\s*-{3,}\s*(?:\n|$)/).map(s => s.trim()).filter(Boolean);
  if (parts.length === 1 && (ctx.replyCount || 1) > 1) {
    const alt = reply.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);
    if (alt.length > 1) parts = alt;
  }
  const cap = Math.max(1, ctx.burstMax || 3);
  if (parts.length > cap) parts = parts.slice(0, cap - 1).concat([parts.slice(cap - 1).join(' ')]);
  parts.forEach((p, i) => {
    const pm = { role: 'persona', content: p, ts: now, proactive: false, burstIndex: i + 1, burstSize: parts.length, analysis: replyA };
    state.messages.push(pm);
    newMessages.push(pm);
  });
  analysis = { user: userA, reply: replyA };
  const idx = state.currentGoalIndex;
  const goal = state.goals[idx];
  if (goal) {
    const before = goal.progress || 0;
    const clamp01 = v => Math.max(0, Math.min(1, Number(v) || 0));
    const fresh = Array.isArray(ev.new_evidence) ? ev.new_evidence.filter(e => e && e.quote) : [];
    goal.evidence = (goal.evidence || []).concat(fresh.map(e => ({ quote: String(e.quote), behavior: String(e.behavior || ''), strength: e.strength === 'strong' ? 'strong' : 'moderate', turn: state.turn }))).slice(-20);
    goal.behaviorScore = clamp01(ev.behavior_score);
    goal.successScore = clamp01(ev.success_score);
    const evCount = goal.evidence.length;
    const strongCount = goal.evidence.filter(e => e.strength === 'strong').length;
    let achieved;
    const ec = goal.evaluationConfig;
    if (ec) {
      goal.checks = {
        behavior: goal.behaviorScore >= ec.behaviorThreshold,
        success: goal.successScore >= ec.successThreshold,
        evidence: evCount >= ec.minEvidenceCount,
        strongEvidence: strongCount >= ec.minStrongEvidenceCount
      };
      achieved = goal.checks.behavior && goal.checks.success && goal.checks.evidence && goal.checks.strongEvidence;
    } else {
      achieved = ev.achieved === true || Number(ev.progress) >= 100;
    }
    goal.progress = Math.max(0, Math.min(100, Math.round(Number(ev.progress) || 0)));
    if (!achieved) goal.progress = Math.min(goal.progress, 95);
    goal.lastReasoning = ev.reasoning || '';
    if (achieved) {
      goal.status = 'achieved';
      goal.progress = 100;
      goal.achievedAt = now;
      state.currentGoalIndex = idx + 1;
      if (state.goals[state.currentGoalIndex]) state.goals[state.currentGoalIndex].status = 'in_progress';
    } else {
      goal.status = 'in_progress';
    }
    goalUpdate = { goalIndex: idx, title: goal.title || '', description: goal.description, previousProgress: before, progress: goal.progress, achieved: goal.status === 'achieved', behaviorScore: goal.behaviorScore, successScore: goal.successScore, evidenceCount: evCount, strongEvidenceCount: strongCount, newEvidence: fresh, checks: goal.checks || null, thresholds: ec || null, reasoning: goal.lastReasoning };
  }
  followUp = ev.should_follow_up === true;
}
const style = (state.persona && state.persona.conversationStyle) || {};
function pick(r, dMin, dMax) {
  const o = r || {};
  const min = Number.isFinite(Number(o.min)) ? Number(o.min) : dMin;
  const max = Number.isFinite(Number(o.max)) ? Number(o.max) : dMax;
  return min + Math.floor(Math.random() * (Math.max(min, max) - min + 1));
}
let burstTarget = 0;
let burstKind = null;
if (ctx.hasUserMessage) {
  burstTarget = followUp && newMessages.length < Math.max(1, ctx.burstMax || 3) ? 1 : 0;
  burstKind = 'follow_up';
} else if (ctx.request.action === 'tick') {
  if (state.messages.length === 0) {
    if (style.startsConversation !== false) { burstTarget = pick(style.burstiness, 1, 1); burstKind = 'opener'; }
  } else {
    const maxNudges = style.inactivityNudges ? Number(style.inactivityNudges.max) || 1 : 2;
    if ((state.nudgesSinceUser || 0) < maxNudges) { burstTarget = 1; burstKind = 'nudge'; state.nudgesSinceUser = (state.nudgesSinceUser || 0) + 1; }
  }
}
burstTarget = Math.min(burstTarget, 5);
const sendProactive = burstTarget > 0;
const currentGoal = state.goals[state.currentGoalIndex] || null;
const transcript = state.messages.slice(-20).map(m => (m.role === 'user' ? 'User' : state.persona.name) + ': ' + m.content).join('\n');
return [{ json: Object.assign({}, ctx, {
  state: state,
  newMessages: newMessages,
  analysis: analysis,
  goalUpdate: goalUpdate,
  sendProactive: sendProactive,
  burstCount: 0,
  burstTarget: burstTarget,
  burstKind: burstKind,
  currentGoal: currentGoal,
  transcript: transcript || '(no messages yet)'
