}
const chatMessages = newMessages.length ? newMessages.map((m, i) => ({ text: m.content, delaySec: i === 0 ? 0.2 : Math.round(Math.min(4000, Math.max(800, m.typingDelayMs)) / 100) / 10 })) : [{ text: chatText, delaySec: 0.2 }];
return [{ json: { source: req.source, sessionId: state.sessionId, stateJson: JSON.stringify(state), response: response, chatText: chatText, chatMessages: chatMessages } }];
